solution:
use xiom.io;

use xiom.string;
fn double(x: Int) -> Int
  ensures: result == x * 2;
{
  return x * 2;
}

fn abs_val(x: Int) -> Int
  ensures: result >= 0;
{
  if x < 0 { return -x; }
  else { return x; }
}

fn main() -> Int {
  io.println(to_string(double(7)));
  io.println(to_string(abs_val(-15)));
  return 0;
}
